seen=set()
dups=0
for row in csv.DictReader(open('inputs/gtfs/stops.txt')):
    key=row['stop_id']+row['stop_name']+row['stop_lat']+row['stop_lon']
    if key in seen:
        dups+=1
    else:
        seen.add(key)
print('duplicate rows',dups)
